#!/usr/bin/env bash
# Run one measurement and save it under results/<date>/ with a header: description +
# generated by, machine, date, data, and the commit of the engine that was measured
# (duckdb commit for the DuckDB kinds, datafusion commit for the datafusion kind).
#
#   scripts/bench_record.sh <kind> <name> "<description>"
#
#   kind        what runs                                   writes
#   timing      scripts/bench_prenest_timing.sh             <name>.tsv
#   plain       scripts/bench_plain_timing.sh               <name>.tsv
#   counters    scripts/bench_prenest_counters.sh           <name>.tsv
#   datafusion  cargo test $DF_TEST in $DF_DIR/benchmarks   <name>_long.csv, <name>_wide.csv
#
# Environment (defaults in brackets):
#   BIN      duckdb binary [<repo>/build/release/duckdb]; its source_id is the "duckdb commit"
#            (DuckDB kinds only)
#   Q        query directory [/choily/tpch-queries], passed to every DuckDB kind
#   OUT      output directory [results/$(date +%F)]
#   DATA     "data:" header [the directory of the first parquet path in $Q/q6.sql]
#   DF_DIR   DataFusion checkout [~/datafusion_research] (datafusion kind only)
#   DF_TEST  [nested::benchmark_tpch_regular::tests::run_active]
#   NESTED_DATA_DIR, TPCH_SF, TPCH_NESTED_VARIANT  passed through to DataFusion
#   FORCE=1  record even if the binary was built from a different src/ than the
#            worktree HEAD
#
# The 2026-09-29 set, for example:
#   scripts/bench_record.sh timing   duckdb_mt       "DuckDB run1: auto=false vs auto=true, default parallelism, 6 runs, first discarded, median of 5, release build, process startup included"
#   scripts/bench_record.sh timing   duckdb_mt_run2  "DuckDB run2: same method as run1"
#   scripts/bench_record.sh counters duckdb_counters "DuckDB: elements_decoded / elements_appended at auto=true, single run"
#   BIN=~/main_wt/build/release/duckdb scripts/bench_record.sh plain duckdb_a_83ae79 "DuckDB (a) stock upstream, no LIST<STRUCT> pruning. 6 runs, first discarded, median of 5, /usr/bin/time -f %e, process startup included"
#   NESTED_DATA_DIR=/data scripts/bench_record.sh datafusion datafusion_mt "DataFusion run1: run_active, ALL_QUERIES x ACTIVE_PARADIGMS, multi_thread, bench-test profile. ratio = col_prune / push_deep_scan"
#
# Existing files are never overwritten. If the DataFusion checkout has local changes
# during a datafusion run, they are saved next to the results as
# datafusion_diff_<hash>.diff and the header points to it.

set -euo pipefail

kind=${1:?usage: $0 timing|plain|counters|datafusion <name> \"<description>\"}
name=${2:?missing <name>}
desc=${3:?missing \"<description>\"}

repo=$(git rev-parse --show-toplevel)
BIN=${BIN:-$repo/build/release/duckdb}
Q=${Q:-/choily/tpch-queries}
OUT=${OUT:-$repo/results/$(date +%F)}
DF_DIR=${DF_DIR:-$HOME/datafusion_research}
DF_TEST=${DF_TEST:-nested::benchmark_tpch_regular::tests::run_active}

die() { echo "bench_record: $*" >&2; exit 1; }

case $kind in
	timing | plain | counters)
		ext=(tsv)
		[ -x "$BIN" ] || die "no duckdb binary at $BIN"
		ls "$Q"/q*.sql >/dev/null 2>&1 || die "no queries in $Q"
		;;
	datafusion)
		ext=(long.csv wide.csv)
		[ -d "$DF_DIR/benchmarks" ] || die "no DataFusion checkout at $DF_DIR"
		;;
	*) die "unknown kind '$kind'" ;;
esac

mkdir -p "$OUT"
outs=()
for e in "${ext[@]}"; do
	[ "$kind" = datafusion ] && f="$OUT/${name}_$e" || f="$OUT/$name.$e"
	[ -e "$f" ] && die "$f exists, not overwriting"
	outs+=("$f")
done

load=$(cut -d' ' -f1 /proc/loadavg)
if awk "BEGIN{exit !($load > 1)}"; then
	echo "bench_record: warning: load average $load, the committed runs were on an idle machine" >&2
fi

# --- header fields -------------------------------------------------------------

# duckdb commit: what the binary was built from, not what the worktree is at now.
duckdb_line() {
	[ -x "$BIN" ] || { echo "unknown (no binary at $BIN)"; return; }
	local sid dir branch
	sid=$("$BIN" -noheader -list -c "SELECT source_id FROM pragma_version()")
	dir=$(cd "$(dirname "$BIN")" && git rev-parse --show-toplevel 2>/dev/null) || { echo "$sid"; return; }
	branch=$(git -C "$dir" branch --show-current)
	git -C "$dir" cat-file -e "$sid^{commit}" 2>/dev/null || { echo "$sid (not a commit in $dir)"; return; }
	# A binary older than the source makes the header lie; refuse unless told otherwise.
	if ! git -C "$dir" diff --quiet "$sid" -- src extension third_party; then
		[ "${FORCE:-}" = 1 ] ||
			die "$BIN was built from $sid but $dir differs from it in src/ (rebuild, or FORCE=1)"
		echo "$sid (branch ${branch:-detached}; worktree differs from the binary in src/)"
		return
	fi
	echo "$sid (branch ${branch:-detached})"
}

datafusion_line() {
	[ -d "$DF_DIR/.git" ] || [ -f "$DF_DIR/.git" ] || { echo "unknown (no checkout at $DF_DIR)"; return; }
	local head branch extra="" diff untracked h
	head=$(git -C "$DF_DIR" rev-parse --short=9 HEAD)
	branch=$(git -C "$DF_DIR" branch --show-current)
	diff=$(git -C "$DF_DIR" diff HEAD)
	untracked=$(git -C "$DF_DIR" ls-files --others --exclude-standard -- benchmarks)
	if [ -n "$diff$untracked" ]; then
		h=$(printf '%s\n%s' "$diff" "$untracked" | sha1sum | cut -c1-8)
		f="$OUT/datafusion_diff_$h.diff"
		if [ ! -e "$f" ]; then
			{
				[ -n "$untracked" ] && printf '# untracked, not in this diff:\n%s\n' "$(sed 's/^/#   /' <<<"$untracked")"
				printf '%s\n' "$diff"
			} >"$f"
		fi
		extra="; local changes: $(basename "$f")"
	fi
	echo "$head (branch ${branch:-detached}$extra)"
}

data_line() {
	if [ -n "${DATA:-}" ]; then
		echo "$DATA"
	elif [ "$kind" = datafusion ]; then
		local sf=${TPCH_SF:-1}
		echo "${NESTED_DATA_DIR:-$HOME/data}/${TPCH_NESTED_VARIANT:-tpch-nested}/$sf/ (SF$sf)"
	else
		# Queries name their parquet files as '<data>/<sf>/<table>/<table>.parquet'.
		local p
		p=$(grep -oh "'[^']*\.parquet'" "$Q"/q6.sql "$Q"/q*.sql 2>/dev/null | head -1 | tr -d "'" || true)
		[ -n "$p" ] || { echo "unknown"; return; }
		p=$(dirname "$(dirname "$p")")
		echo "$p/ (SF$(basename "$p"))"
	fi
}

# Record the state before the run, so a rebuild or checkout during it cannot leak in.
# Only the measured engine's commit goes in the header.
if [ "$kind" = datafusion ]; then
	h_commit="datafusion commit: $(datafusion_line)"
else
	h_commit="duckdb commit: $(duckdb_line)"
fi
h_data=$(data_line)
h_date=$(date +%F)

header() {
	printf '# %s. generated by: %s\n' "${desc%.}" "$1"
	printf '# machine: %s\n' "$(hostname)"
	printf '# date: %s\n' "$h_date"
	printf '# data: %s\n' "$h_data"
	printf '# %s\n' "$h_commit"
}

# --- run -----------------------------------------------------------------------

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

# A failed duckdb run leaves its error text where a time should be; catch that here
# rather than in the committed file.
check_numeric() {
	awk -F'\t' 'NR > 1 { for (i = 2; i <= NF; i++) if ($i !~ /^[0-9.]+$/) { print FILENAME ": line " NR ": " $0; bad = 1 } }
		END { exit bad }' "$1" >&2 || die "non-numeric cells in the output above"
}

case $kind in
	timing)
		BIN=$BIN Q=$Q "$repo/scripts/bench_prenest_timing.sh" >"$tmp/out"
		check_numeric "$tmp/out"
		{ header "BIN=$BIN Q=$Q scripts/bench_prenest_timing.sh"; cat "$tmp/out"; } >"${outs[0]}"
		;;
	plain)
		BIN=$BIN Q=$Q "$repo/scripts/bench_plain_timing.sh" >"$tmp/out"
		check_numeric "$tmp/out"
		{ header "BIN=$BIN Q=$Q scripts/bench_plain_timing.sh"; cat "$tmp/out"; } >"${outs[0]}"
		;;
	counters)
		BIN=$BIN QDIR=$Q "$repo/scripts/bench_prenest_counters.sh" >"$tmp/out"
		{ header "BIN=$BIN QDIR=$Q scripts/bench_prenest_counters.sh"; cat "$tmp/out"; } >"${outs[0]}"
		;;
	datafusion)
		cargo=$(command -v cargo || echo "$HOME/.cargo/bin/cargo")
		# The test writes results/runtime/<name>.csv and <name>_wide.csv; the name
		# depends on the checkout, so take whatever this run produced.
		touch "$tmp/marker"
		(cd "$DF_DIR/benchmarks" && RUSTFLAGS="-A warnings" "$cargo" test --profile bench-test --lib \
			"$DF_TEST" -- --exact --show-output) | tee "$tmp/log"
		wide=$(find "$DF_DIR/benchmarks/results/runtime" -name '*_wide.csv' -newer "$tmp/marker")
		[ "$(wc -l <<<"$wide")" = 1 ] && [ -n "$wide" ] ||
			die "expected one new *_wide.csv under $DF_DIR/benchmarks/results/runtime, found: ${wide:-none}"
		long=${wide%_wide.csv}.csv
		[ -f "$long" ] || die "no $long next to $wide"
		cmd="NESTED_DATA_DIR=${NESTED_DATA_DIR:-} cargo test --profile bench-test --lib $DF_TEST (in $DF_DIR/benchmarks)"
		{ header "$cmd"; cat "$long"; } >"${outs[0]}"
		{ header "$cmd"; cat "$wide"; } >"${outs[1]}"
		;;
esac

printf 'wrote %s\n' "${outs[@]}"
